describe('Registry loading [specs/hal-engine-tool-input-validation/spec.md#3]', () => {
  it('loads the registry and executes valid location input unchanged', async () => {
    const {ToolRegistry} = await import('./registry.js');
    const registry = new ToolRegistry();
    registry.register(
      {
        name: 'location',
        description: 'Echo the supplied location',
        inputSchema: {type: 'object', properties: {location: {type: 'string'}}, required: ['location']},
      },
      async input => JSON.stringify(input),
    );

    const input = {location: 'Berlin', units: 'metric'};
    const response = await registry.execute('location', input);

    expect(JSON.parse(response.result)).toEqual(input);
  });
});
EOF
